// tb.v: random-stimulus testbench for CdcTop, generated by tests/unit/test_emit.c.
// Prints the outputs every cycle; test_emit compares them with the Tern simulator.
`timescale 1ns/1ps
module tb;
    reg sys_clk = 1'b0;
    reg pix_clk = 1'b0;
    reg sys_rst_n = 1'b1;
    reg pix_arst = 1'b0;
    reg [7:0] din = 8'd0;
    reg [3:0] cfg = 4'd0;
    wire flag_pix;
    wire [7:0] data_pix;
    wire [3:0] cfg_pix;
    wire [3:0] pix_count;
    wire pix_in_reset;
    reg [11:0] stim [0:239];
    integer i;

    CdcTop dut (
        .sys_clk(sys_clk),
        .sys_rst_n(sys_rst_n),
        .pix_clk(pix_clk),
        .din(din),
        .cfg(cfg),
        .flag_pix(flag_pix),
        .data_pix(data_pix),
        .cfg_pix(cfg_pix),
        .pix_arst(pix_arst),
        .pix_count(pix_count),
        .pix_in_reset(pix_in_reset)
    );

    task cycle_sys_clk;
        begin
            sys_clk = 1'b1;
            #5;
            sys_clk = 1'b0;
            #5;
        end
    endtask

    task cycle_pix_clk;
        begin
            pix_clk = 1'b1;
            #5;
            pix_clk = 1'b0;
            #5;
        end
    endtask

    task do_reset;
        begin
            sys_rst_n = 1'b0;
            pix_arst = 1'b1;
            #1;
            cycle_sys_clk;
            cycle_sys_clk;
            cycle_pix_clk;
            cycle_pix_clk;
            sys_rst_n = 1'b1;
            pix_arst = 1'b0;
            #1;
        end
    endtask

    initial begin
        $readmemh("stim.hex", stim);
        #1;
        for (i = 0; i < 240; i = i + 1) begin
            if (i == 0 || i == 120)
                do_reset;
            {din, cfg} = stim[i];
            #1;
            $display("D %0d %h %h %h %h %h", i, flag_pix, data_pix, cfg_pix, pix_count, pix_in_reset);
            cycle_sys_clk;
            cycle_pix_clk;
        end
        $finish;
    end
endmodule
